INSERT INTO "main"."Bot" ("id", "createdAt", "updatedAt", "name", "avatar", "description", "isOfficial") VALUES (4, '1742958063422', 1742958042609, 'AI Portrait Generator - Floral Style', 'https://www.myshellstatic.com/cdn-cgi/image/quality=40,format=webp/image/bot/logo/4195582/202502210344/28-cropped-image.png', '<h2>Wish you could have a flower-filled photoshoot? Try MyShell AI Portrait Generator - Floral Style! 🌻🌻</h2> Pick one template, upload your photo, and get a masterpiece in 60 seconds.', 0);